                out = {"error": str(e)}
            results.append({"type": "tool_result", "tool_use_id": c["id"], "content": json.dumps(out, default=str)})
        messages.append({"role": "user", "content": results})


if __name__ == "__main__":
    print(answer(" ".join(sys.argv[1:])))

